// Alarmes affichées – contrôle de la demande de l'interface :
//   { }                          les alarmes non acquittées
//   { historique: true }         + les alarmes acquittées des 24 dernières heures
//   { acquitter: "<uuid>" }      acquitte une alarme
const e = $input.first().json?.body ?? {};
let acquitter = '';
if (e.acquitter !== undefined) {
  acquitter = String(e.acquitter);
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(acquitter)) throw new Error('acquitter : identifiant invalide');
}
return [{ json: { acquitter, historique: e.historique === true ? 'true' : '' } }];

// Alarmes affichées – réponse à l'interface (les alarmes non acquittées des 12 dernières heures, la plus récente d'abord).
const lignes = $input.all().map((i) => i.json).filter((r) => r.id);
return [
  {
    json: {
      alarmes: lignes.map((r) => ({
        id: r.id,
        recue_le: r.recue_le,
        chambre: r.chambre,
        type: r.type,
        libelle: r.libelle,
        faits: r.faits,
        contexte: r.contexte ?? { statut: 'aucun' },
        statut: r.statut ?? 'nouvelle',
        acquittee_le: r.acquittee_le ?? null,
      })),
    },
  },
];

// Contrôle de session – le jeton « Bearer » de l'en-tête Authorization (43 caractères URL-safe) est haché (SHA-256) : seul le haché est en base.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Contrôle de session – résultat : un soignant identifié (session ouverte, non expirée, compte actif) ou rien.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
